using System.ComponentModel.DataAnnotations;
using DineFlow.Application.Promotions;
using DineFlow.Domain.Payments;

namespace DineFlow.Application.Payments;

/// <param name="ClientRequestId">Generated by the guest app per attempt and reused on retry.</param>
/// <param name="ExpectedRemainingMinor">What the guest saw left to pay; if the bill changed, nothing is charged.</param>
/// <param name="AcceptTerms">The guest agreed to the Terms and Conditions shown next to the pay button.</param>
public record CreatePaymentRequest(
    [Required] Guid SessionId,
    [Required] Guid ClientRequestId,
    [Required] PaymentMethod Method,
    [Range(0, 100_000_000)] long TipMinor,
    [StringLength(20)] string? PromoCode,
    [Range(1, 100_000_000)] long ExpectedRemainingMinor,
    bool AcceptTerms);

public record ReceiptRequest([Required, EmailAddress, StringLength(254)] string Email);

/// <summary>A payment as the guest sees it, plus where the bill stands and an offer once it has succeeded.</summary>
public record PaymentDto(
    Guid Id,
    string Reference,
    PaymentStatus Status,
    PaymentMethod Method,
    string Currency,
    long BillAmountMinor,
    long DiscountMinor,
    long TipMinor,
    long AmountMinor,
    string? PromoCode,
    string? CardBrand,
    string? CardLast4,
    string? FailureReason,
    /// <summary>The provider's page to send the guest to while the payment needs their action.</summary>
    string? CheckoutUrl,
    string LocationType,
    string LocationLabel,
    string? AreaName,
    DateTimeOffset CreatedAt,
    DateTimeOffset? SucceededAt,
    /// <summary>What's still owed on the bill after this payment (known once it succeeded).</summary>
    long? RemainingMinor,
    bool? FullyPaid,
    NextVisitOfferDto? NextVisitOffer);
